import { useQuery } from '@tanstack/react-query';
import axios from 'axios';
import { StplatResponse } from '~/entities/pin/api/dtos/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { QueryOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { queries } from '~/shared/api/query-keys';
import { resultify } from '~/shared/lib/utils/resultify';

const getStplatReadList = () => {
  return resultify(axios.post<StplatResponse[]>(`${API_URLS.stplatReadList}`));
};

export const useStplatReadListQuery = (options?: QueryOptions<StplatResponse[], CBDCAxiosError>) => {
  return useQuery<StplatResponse[], CBDCAxiosError>({
    queryKey: queries.appData.appInfo.queryKey,
    queryFn: () => getStplatReadList(),
    ...options,
  });
};
